long long seg[4*N], lazy[4*N];
void push(int node, int lo, int hi) {
    if (!lazy[node]) return;
    int mid = (lo+hi)/2;
    for (int ch : {2*node, 2*node+1}) {
        int len = (ch == 2*node) ? mid - lo + 1 : hi - mid;
        seg[ch] += lazy[node] * len;
        lazy[ch] += lazy[node];
    }
    lazy[node] = 0;
}
void update(int node,int lo,int hi,int l,int r,long long v){
    if (r < lo || hi < l) return;
    if (l <= lo && hi <= r){ seg[node]+=v*(hi-lo+1); lazy[node]+=v; return; }
    push(node, lo, hi); int mid=(lo+hi)/2;
    update(2*node,lo,mid,l,r,v); update(2*node+1,mid+1,hi,l,r,v);
    seg[node]=seg[2*node]+seg[2*node+1];
}

class LazySeg:
    def __init__(self, n):
        self.n = n
        self.seg = [0] * (4 * n)
        self.lazy = [0] * (4 * n)
    def _push(self, node, lo, hi):
        if not self.lazy[node]:
            return
        mid = (lo + hi) // 2
        for ch, length in ((2*node, mid - lo + 1), (2*node+1, hi - mid)):
            self.seg[ch] += self.lazy[node] * length
            self.lazy[ch] += self.lazy[node]
        self.lazy[node] = 0
    def update(self, node, lo, hi, l, r, v):
        if r < lo or hi < l:
            return
        if l <= lo and hi <= r:
            self.seg[node] += v * (hi - lo + 1)
            self.lazy[node] += v
            return
        self._push(node, lo, hi)
        mid = (lo + hi) // 2
        self.update(2*node, lo, mid, l, r, v)
        self.update(2*node+1, mid+1, hi, l, r, v)
        self.seg[node] = self.seg[2*node] + self.seg[2*node+1]
